import{_ as s,o as a,c as o,a6 as t}from"./chunks/framework.FpL9Zs30.js";const u=JSON.parse('{"title":"The catalog changes by exercise revision, not by catalog version","description":"","frontmatter":{"status":"accepted","date":"2026-11-14T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version.md","filePath":"docs/adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version.md"}'),n={name:"docs/adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version.md"};function i(r,e,h,c,l,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="the-catalog-changes-by-exercise-revision-not-by-catalog-version" tabindex="-1">The catalog changes by exercise revision, not by catalog version <a class="header-anchor" href="#the-catalog-changes-by-exercise-revision-not-by-catalog-version" aria-label="Permalink to &quot;The catalog changes by exercise revision, not by catalog version&quot;">​</a></h1><p>Supersedes the catalog version of <a href="./0008-curated-catalog-with-stable-slugs">ADR 0008</a>, <a href="./0015-catalog-text-lives-in-translation-files">ADR 0015</a> and <a href="./0026-the-server-holds-the-catalog-as-a-draft-and-published-versions">ADR 0026</a> (<a href="https://github.com/tkint/coach-poulpy/issues/400" target="_blank" rel="noreferrer">#400</a>).</p><p>ADR 0026 numbers every publication (<code>catalog_version</code>) and serves &quot;the latest version&quot; whole. A catalog-wide number is a release concept the catalog doesn&#39;t need: fixing one exercise&#39;s French would make a new version of every exercise, and every phone would compare, store and download a number to learn whether it is up to date. The unit of change is the exercise. What stays: stable slugs, retiring instead of deleting, the draft, revisions stored per exercise, the translation files that own the <em>bundled</em> text, and catalog updates that need no account.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><ul><li><strong>An exercise has revisions.</strong> Its published revisions are numbered 1, 2, 3… by the server (<code>revision</code>) and never change. Editing starts a draft revision after the latest published one; publishing gives it the next number. Nothing else changes: publishing an exercise writes that exercise only, and there is no catalog version, release number, snapshot or counter that names the catalog as a whole.</li><li><strong>Retiring and offering again are revisions</strong> of the exercise (the <code>retired</code> flag), published like any edit. They are lifecycle changes, not events of the catalog.</li><li><strong>A variation group is no entity of its own.</strong> Each member&#39;s revision carries its group and its rank, as in ADR 0026. Reordering a group publishes a new revision of each member whose rank changed.</li><li><strong>The admin publishes exercises</strong>: one, several or all of the pending ones, in one transaction. Publishing never touches the exercises it doesn&#39;t name.</li></ul><h2 id="how-a-phone-asks-for-changes-the-cursor" tabindex="-1">How a phone asks for changes: the cursor <a class="header-anchor" href="#how-a-phone-asks-for-changes-the-cursor" aria-label="Permalink to &quot;How a phone asks for changes: the cursor&quot;">​</a></h2><p>A phone doesn&#39;t compare a catalog number. It asks for what was published since the last answer it stored.</p><ul><li>Every published revision takes the next number of a <strong>publication cursor</strong> (<code>seq</code>), a counter of publications on the server, taken under a lock on the catalog so numbers follow commit order and a phone never skips a revision committed late. This is the pull cursor of <a href="./0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes">ADR 0025</a> over the stream of published revisions. It is <strong>not</strong> a catalog version: it names a position in a stream, not a state of the catalog; nobody compares two cursors, shows one or decides anything from its value; the phone only echoes the last one it received; the bundled catalog has none; and no exercise&#39;s identity depends on it. The identity of what an exercise holds is its slug and its <code>revision</code>.</li><li><code>GET /api/v1/catalog/exercises?after=&lt;cursor&gt;</code> answers the exercises whose latest published revision is newer than the cursor, each as its full JSON with its <code>revision</code>, and the new cursor: <code>{cursor, exercises}</code>. Without <code>after</code>, it answers every exercise, which is the clean first download and the full refresh. When there is nothing newer, <code>204</code>. It needs no account.</li><li><strong>The phone applies the answer in one database transaction</strong>, the exercises and the new cursor together, so an interrupted or failed update leaves the old cursor and the old exercises, and asking again is always safe. It keeps an exercise only if the answer&#39;s <code>revision</code> is higher than its own. Offline, it uses what it has, as it does now.</li><li><strong>The bundled catalog carries no cursor.</strong> Its exercises are revision 1. The first launch after a fresh install, or after the cursor was lost, downloads the whole catalog once; every later launch downloads only the changes.</li></ul><h2 id="existing-data" tabindex="-1">Existing data <a class="header-anchor" href="#existing-data" aria-label="Permalink to &quot;Existing data&quot;">​</a></h2><p>The beta APKs (v0.x) hold the catalog in the phone&#39;s database with the bundled file&#39;s version, and the server holds the numbered versions. Nothing is reset:</p><ul><li><strong>Phone:</strong> a new SQLDelight migration adds the exercise&#39;s <code>revision</code> and a one-row cursor table, keeps every row and slug, and gives each stored exercise revision 1. Workouts and sessions reference exercises by slug and are not touched. The old catalog <code>version</code> is read by nothing once the app uses revisions; its column is dropped by a later migration, after the apps that read it are no longer in use (marked <code>CLEANUP:</code>).</li><li><strong>Server:</strong> a new Postgres migration adds <code>revision</code> and <code>seq</code> to <code>catalog_exercise_revision</code>, filled from the published revisions in publication order, keeping every slug and every published revision. <code>catalog_version</code> and <code>published_in</code> stay, marked <code>CLEANUP:</code>, until nothing reads them; a later migration drops them.</li><li><strong>Compatibility:</strong> no released app downloads from the server yet, so <code>GET /api/v1/catalog</code> is kept until <code>GET /api/v1/catalog/exercises</code> ships and is then removed.</li><li><strong>The repository&#39;s catalog files</strong> stay the source of the bundled catalog. Each exercise there may carry a <code>revision</code> (1 when absent), and CI checks that an exercise whose content changed has a higher <code>revision</code>, in place of the catalog version check of ADR 0015.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep the catalog version and bump it on every publish.</strong> It is what exists; it makes one exercise&#39;s fix a catalog release and has every phone compare a number that doesn&#39;t mean anything about one exercise.</li><li><strong>A catalog watermark under another name</strong> (the highest revision, or a hash of all of them). It would behave as a catalog version, which the issue rules out. The cursor is allowed only because it is opaque to the phone and stands for a position in a stream.</li><li><strong>The phone sends what it has</strong> (every slug with its revision) and the server answers the difference. No cursor, but every launch sends and compares the whole catalog.</li><li><strong>Only the full catalog, always.</strong> The simplest contract, but every launch downloads everything to learn that nothing changed.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The admin&#39;s publish and retirement screens (<a href="https://github.com/tkint/coach-poulpy/issues/389" target="_blank" rel="noreferrer">#389</a>, <a href="https://github.com/tkint/coach-poulpy/issues/390" target="_blank" rel="noreferrer">#390</a>) publish exercises and no longer name a version; the admin shows what is pending per exercise.</li><li>A phone keeps only the latest revision of an exercise it has applied. A workout shows the exercise&#39;s latest text, as it does today; what a finished session stored about its exercises is not rewritten and not changed by this decision.</li><li>Publishing is serialised on the server, which suits one admin and a few publications a day.</li><li>The work is split: this decision, then the server and its API, the Android and iOS clients, the admin, and the CI and documentation. The documentation that describes the running code (<a href="./../the-api">the API</a>, <a href="./../admin">the admin</a>, the glossary) changes with the code, not with this ADR.</li></ul>',15)])])}const p=s(n,[["render",i]]);export{u as __pageData,p as default};
